import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;

public class ReportExportServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(ReportExportServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String sessionToken = req.getHeader("X-Session-Token");
        if (sessionToken == null || sessionToken.isEmpty()) {
            resp.sendError(401, "Missing session token");
            return;
        }

        // Validate session exists (but doesn't prevent SQLi below)
        if (!validateSession(sessionToken)) {
            resp.sendError(403, "Invalid session");
            return;
        }

        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String customFilter = req.getParameter("filter");
        String sortCol = req.getParameter("sort");
        String format = req.getParameter("format");

        if (reportType == null || !reportType.matches("(sales|inventory|audit)")) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        if (format == null) format = "csv";
        if (!format.matches("(csv|json|xml)")) {
            resp.sendError(400, "Invalid format");
            return;
        }

        // Date range is validated
        if (dateRange != null && !dateRange.matches("\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        // Sort column whitelist
        if (sortCol != null && !sortCol.matches("(created_at|amount|item_id|status)")) {
            sortCol = "created_at";
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            String table = "report_" + reportType;
            StringBuilder query = new StringBuilder();
            query.append("SELECT * FROM ").append(table);

            if (dateRange != null) {
                String[] parts = dateRange.split("_");
                query.append(" WHERE created_at BETWEEN '").append(parts[0])
                     .append("' AND '").append(parts[1]).append("'");
            }

            // customFilter is NOT sanitized - SQL injection vector
            if (customFilter != null && !customFilter.isEmpty()) {
                if (dateRange != null) {
                    query.append(" AND ").append(customFilter);
                } else {
                    query.append(" WHERE ").append(customFilter);
                }
            }

            if (sortCol != null) {
                query.append(" ORDER BY ").append(sortCol);
            }

            query.append(" LIMIT 10000");

            log.info("Executing report query for type=" + reportType);
            Statement stmt = conn.createStatement();
            ResultSet rs = stmt.executeQuery(query.toString());

            resp.setContentType(getContentType(format));
            resp.setHeader("Content-Disposition", "attachment; filename=report." + format);

            PrintWriter out = resp.getWriter();
            ResultSetMetaData meta = rs.getMetaData();
            int cols = meta.getColumnCount();

            if ("csv".equals(format)) {
                for (int i = 1; i <= cols; i++) {
                    out.print(meta.getColumnName(i));
                    if (i < cols) out.print(",");
                }
                out.println();
                while (rs.next()) {
                    for (int i = 1; i <= cols; i++) {
                        out.print(rs.getString(i));
                        if (i < cols) out.print(",");
                    }
                    out.println();
                }
            }
            rs.close();
            stmt.close();
        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    private boolean validateSession(String token) {
        // Checks token format and expiry against Redis - not relevant to SQLi
        return token.length() == 64 && token.matches("[a-f0-9]+");
    }

    private String getContentType(String format) {
        switch (format) {
            case "json": return "application/json";
            case "xml": return "application/xml";
            default: return "text/csv";
        }
    }
}
